inputs.default:
{
  "type": "object",
  "properties": {
    "query": { "type": "string", "description": "Free-text keywords, e.g. '10k 0603 resistor' or an MPN.", "minLength": 2 },
    "category": { "type": "string", "enum": ["resistor", "capacitor", "inductor", "ic", "connector"], "description": "Part family to search in." },
    "package": { "type": "string", "description": "Footprint name such as 0603 or SOT-23." },
    "in_stock": { "type": "boolean", "default": true, "description": "Only parts the distributor has in stock." },
    "limit": { "type": "integer", "minimum": 1, "maximum": 50, "default": 10, "description": "How many matches to return." },
    "filters": { "type": "object", "description": "Electrical limits the part must meet.", "properties": {
      "tolerance_pct": { "type": "number", "maximum": 20 },
      "voltage_min": { "type": "number", "description": "Minimum rated voltage in volts." } } },
    "tags": { "type": "array", "items": { "type": "string" }, "maxItems": 5 }
  },
  "required": ["query"]
}

/** Search the component library. */
function searchParts(
  /** Free-text keywords or an MPN. */
  query: string,
  /** Part family to search in. */
  category?: "resistor" | "capacitor" | "ic",
  /** How many matches to return. */
  limit: number = 10,
  tags?: string[],
): Promise<Part[]>
